29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public String getAddress() {
61	        return this.address;
62	    }
63	
64	    public void setAddress(String address) {
65	        this.address = address;
66	    }
67	
68	    public String getCity() {
69	        return this.city;
70	    }
71	
72	    public void setCity(String city) {
73	        this.city = city;
74	    }
75	
76	    public String getTelephone() {
77	        return this.telephone;
78	    }
79	
80	    public void setTelephone(String telephone) {
81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    public void setEmail(String email) {
89	        this.email = email;
90	    }
91	
92	    public LocalDate getRegistrationDate() {
93	        return this.registrationDate;
94	    }
95	
96	    public void setRegistrationDate(LocalDate registrationDate) {
97	        this.registrationDate = registrationDate;
98	    }
99	
100	    protected Set<Pet> getPetsInternal() {
101	        if (this.pets == null) {
102	            this.pets = new HashSet<>();
103	        }
104	        return this.pets;
105	    }
106	
107	    protected void setPetsInternal(Set<Pet> pets) {
108	        this.pets = pets;
109	    }
110	
111	    public List<Pet> getPets() {
112	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
113	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
114	        return Collections.unmodifiableList(sortedPets);
115	    }
116	
117	    public void setPets(List<Pet> pets) {
118	        this.pets = new HashSet<>(pets);
119	    }
120	
121	    public void addPet(Pet pet) {
122	        getPetsInternal().add(pet);
123	        pet.setOwner(this);
124	    }
125	
126	    /**
127	     * Return the Pet with the given name, or null if none found for this Owner.
128	     *
129	     * @param name to test
130	     * @return true if pet name is already in use
131	     */
132	    public Pet getPet(String name) {
133	        return getPet(name, false);
